{"packet_id":"D032-04","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken initial rental decontrol upon vacancy by bona fide condo/co-op owner-occupant","requirement":"When a bona fide condo/co-op owner-occupant vacates the unit and offers it for rental, the unit is decontrolled only to set the initial rent, which is the amount charged in the first lease after the owner vacates; the unit is otherwise fully subject to Chapter 155.","key_value":"initial rent = amount charged in initial lease after vacancy","coverage_conditions":"Condo/co-op units whose owner has continuously occupied the unit as principal residence for the previous two years and then vacates and offers it for rent.","applicability":{"conditions":[{"type":"other","role":"covered","text":"condo/co-op units owned and occupied by a bona fide owner-occupant for two years"}],"per_tenancy":"Decontrol applies only where the owner vacates the unit and offers it for rental.","coverage_quotes":["In the event that an individual who qualifies as a bona fide CCOO vacates his/her condo/co-op unit and offers it for rental"]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Hoboken Mun. Code § 155-37","quoted_span":"In the event that an individual who qualifies as a bona fide CCOO vacates his/her condo/co-op unit and offers it for rental, said unit is decontrolled solely for the purpose of establishing the initial rent subsequent to the bona fide CCOO vacating.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D032-04","doc_id":"D032","jurisdiction":"Hoboken, NJ","category":"rent_increase_limits","lifecycle":"enacted","title":"Hoboken COVID-19 temporary moratorium on rent increases","requirement":"From April 1, 2020 until May 7, 2022, no rent or other rental charge for property covered by Chapter 155 could be increased, including surcharges, parking, pets and deposits; deferred increases are prospective only, with no 2020 CPI increase.","key_value":"no rent or charge increase; 2020-04-01 to 2022-05-07","coverage_conditions":"All tenancies and properties covered by Chapter 155 of the Hoboken City Code.","applicability":{"conditions":[],"per_tenancy":null,"coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2020-04-01","valid_through":"2022-05-07","citation":"Hoboken Mun. Code § 155-38","quoted_span":"A moratorium shall be in effect to prevent any increase in the amount paid in rent or any additional charges whatsoever by tenants covered by this chapter.","interaction":null,"relations":[],"confidence":0.9,"conflict_flag":false,"conflict_note":null}
